Introduction Due to SageMaker Pipelines quota limits, we build a pipeline using a Python function as a replacement. This pipeline automates the entire workflow from data processing, training to model saving.
Pipeline Function import pandas as pd import xgboost as xgb from sklearn.metrics import accuracy_score from sklearn.model_selection import train_test_split import joblib import tarfile import os import boto3 from config import bucket def run_pipeline(input_s3_uri, learning_rate=0.01, max_depth=3, n_estimators=100): print(&#34;=&#34; * 50) print(&#34;TITANIC ML PIPELINE STARTED&#34;) print(&#34;=&#34; * 50) # Step 1: Data Processing print(&#34;
[Step 1/4] Data Processing...&#34;) df = pd.read_csv(input_s3_uri) df[&#34;Age&#34;].fillna(df[&#34;Age&#34;].median(), inplace=True) df[&#34;Embarked&#34;].fillna(df[&#34;Embarked&#34;].mode()[0], inplace=True) df.drop(columns=[&#34;Cabin&#34;], inplace=True) df[&#34;FamilySize&#34;] = df[&#34;SibSp&#34;] + df[&#34;Parch&#34;] + 1 df[&#34;IsAlone&#34;] = (df[&#34;FamilySize&#34;] == 1).astype(int) df[&#34;Title&#34;] = df[&#34;Name&#34;].str.extract(r&#34; ([A-Za-z]+)\.&#34;, expand=False) df[&#34;Title&#34;] = df[&#34;Title&#34;].replace( [&#34;Lady&#34;,&#34;Countess&#34;,&#34;Capt&#34;,&#34;Col&#34;,&#34;Don&#34;,&#34;Dr&#34;,&#34;Major&#34;,&#34;Rev&#34;,&#34;Sir&#34;,&#34;Jonkheer&#34;,&#34;Dona&#34;], &#34;Rare&#34; ) df[&#34;Title&#34;] = df[&#34;Title&#34;].replace({&#34;Mlle&#34;:&#34;Miss&#34;,&#34;Ms&#34;:&#34;Miss&#34;,&#34;Mme&#34;:&#34;Mrs&#34;}) df[&#34;Sex&#34;] = df[&#34;Sex&#34;].map({&#34;male&#34;: 0, &#34;female&#34;: 1}) df[&#34;Embarked&#34;] = df[&#34;Embarked&#34;].map({&#34;S&#34;: 0, &#34;C&#34;: 1, &#34;Q&#34;: 2}) df[&#34;Title&#34;] = df[&#34;Title&#34;].map({&#34;Mr&#34;:0,&#34;Miss&#34;:1,&#34;Mrs&#34;:2,&#34;Master&#34;:3,&#34;Rare&#34;:4}) FEATURES = [&#34;Pclass&#34;,&#34;Sex&#34;,&#34;Age&#34;,&#34;SibSp&#34;,&#34;Parch&#34;,&#34;Fare&#34;,&#34;Embarked&#34;,&#34;FamilySize&#34;,&#34;IsAlone&#34;,&#34;Title&#34;] TARGET = &#34;Survived&#34; df_final = df[FEATURES + [TARGET]].dropna() train_df, test_df = train_test_split( df_final, test_size=0.2, random_state=42, stratify=df_final[TARGET] ) print(f&#34; Train: {train_df.shape} | Test: {test_df.shape}&#34;) # Step 2: Upload processed data print(&#34;
[Step 2/4] Upload processed data...&#34;) os.makedirs(&#34;pipeline/processed&#34;, exist_ok=True) train_df.to_csv(&#34;pipeline/processed/train.csv&#34;, index=False) test_df.to_csv(&#34;pipeline/processed/test.csv&#34;, index=False) s3 = boto3.client(&#34;s3&#34;) s3.upload_file(&#34;pipeline/processed/train.csv&#34;, bucket, &#34;pipeline/processed/train.csv&#34;) s3.upload_file(&#34;pipeline/processed/test.csv&#34;, bucket, &#34;pipeline/processed/test.csv&#34;) print(f&#34; Uploaded to s3://{bucket}/pipeline/processed/&#34;) # Step 3: Training print(&#34;
[Step 3/4] Training XGBoost...&#34;) X_train = train_df[FEATURES] y_train = train_df[TARGET] X_test = test_df[FEATURES] y_test = test_df[TARGET] model = xgb.XGBClassifier( max_depth=max_depth, n_estimators=n_estimators, learning_rate=learning_rate, eval_metric=&#34;logloss&#34;, random_state=42, verbosity=0, ) model.fit(X_train, y_train) acc = accuracy_score(y_test, model.predict(X_test)) print(f&#34; Accuracy: {acc:.4f}&#34;) # Step 4: Save model print(&#34;
[Step 4/4] Save model...&#34;) os.makedirs(&#34;pipeline/models&#34;, exist_ok=True) model.save_model(&#34;pipeline/models/xgboost-model&#34;) with tarfile.open(&#34;pipeline/models/model.tar.gz&#34;, &#34;w:gz&#34;) as tar: tar.add(&#34;pipeline/models/xgboost-model&#34;, arcname=&#34;xgboost-model&#34;) s3.upload_file(&#34;pipeline/models/model.tar.gz&#34;, bucket, &#34;pipeline/models/model.tar.gz&#34;) print(f&#34; Model saved: s3://{bucket}/pipeline/models/model.tar.gz&#34;) print(&#34;
&#34; + &#34;=&#34; * 50) print(&#34;PIPELINE COMPLETED!&#34;) print(f&#34; Accuracy: {acc:.4f}&#34;) print(&#34;=&#34; * 50) return { &#34;accuracy&#34;: acc, &#34;learning_rate&#34;: learning_rate, &#34;max_depth&#34;: max_depth, &#34;n_estimators&#34;: n_estimators, &#34;model_s3&#34;: f&#34;s3://{bucket}/pipeline/models/model.tar.gz&#34; } Run Pipeline result = run_pipeline( input_s3_uri=f&#34;s3://sagemaker-ap-southeast-2-921736623375/data/raw/titanic_raw.csv&#34;, learning_rate=0.01, max_depth=3, n_estimators=100, ) print(f&#34;Accuracy: {result[&#39;accuracy&#39;]:.4f}&#34;) Results Pipeline runs end-to-end automatically Accuracy: 84.92% Model artifact: s3://sagemaker-ap-southeast-2-921736623375/pipeline/models/model.tar.gz
